        const auto callable = ordering
            ? parsed.values.size() >= 4
                ? std::optional<Expr>(parsed.values[3]) : std::nullopt
            : parsed.values.size() >= 3
                ? std::optional<Expr>(parsed.values[2]) : std::nullopt;
